import{_ as t,o as i,c as l,j as e,a as n,a3 as s}from"./chunks/framework.z_KJ15Ep.js";const a="/bilder/grundlagen/schueler-versetzung-1.png",h="/bilder/grundlagen/schueler-versetzung-2.png",u="/bilder/grundlagen/schueler-versetzung-3.png",d="/bilder/grundlagen/schueler-versetzung-7-versetzungstabelle.png",c="/bilder/grundlagen/schueler-versetzung-4.png",o="/bilder/grundlagen/schueler-versetzung-5-datenpruefen.png",z=JSON.parse('{"title":"Halbjahres- und Schuljahreswechsel durchführen","description":"","frontmatter":{"title":"Halbjahres- und Schuljahreswechsel durchführen","source_pageid":728,"source_revision":7170},"headers":[],"relativePath":"einstieg/grundlagen/versetzung-ins-neue-schuljahr-und-abschnittswechsel-durchfuehren-einfuehrung-in-schild-nrw.md","filePath":"einstieg/grundlagen/versetzung-ins-neue-schuljahr-und-abschnittswechsel-durchfuehren-einfuehrung-in-schild-nrw.md"}'),g={name:"einstieg/grundlagen/versetzung-ins-neue-schuljahr-und-abschnittswechsel-durchfuehren-einfuehrung-in-schild-nrw.md"};function b(p,r,m,w,f,k){return i(),l("div",null,[...r[0]||(r[0]=[e("h1",{id:"halbjahres-und-schuljahreswechsel-durchfuhren",tabindex:"-1"},[n("Halbjahres- und Schuljahreswechsel durchführen "),e("a",{class:"header-anchor",href:"#halbjahres-und-schuljahreswechsel-durchfuhren","aria-label":'Permalink to "Halbjahres- und Schuljahreswechsel durchführen"'},"​")],-1),e("p",null,"Übertragen Sie die Schule in einen neuen Lernabschnitt. Unterscheiden Sie den Halbjahreswechsel ohne Versetzung vom Schuljahreswechsel mit Versetzung, Abschlüssen und Ausschulungen.",-1),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),n("Tipp")]),e("p",null,"Vor großen Datenbankaktionen empfiehlt es sich, ein Backup der Datenbank anzulegen.")],-1),e("p",null,"Der Schuljahres- oder Halbjahreswechsel kann in SchILD-NRW auf verschiedene Arten durchgeführt werden. Entscheidend sind oft die Schulform und die Arbeitsweise an der jeweiligen Schule.",-1),e("p",null,[n("Grundsätzlich gilt, dass der Weg über "),e("em",null,"Schulverwaltung ➜ Schule"),n(" bearbeiten gewählt werden kann.")],-1),e("p",null,"Die Schüler klassen- oder jahrgangsweise über den Gruppenprozess zu versetzen ist nur notwendig, wenn es an der Schule Jahrgänge oder Klassen gibt, die zu verschiedenen Zeitpunkten oder von verschiedenen Abteilungsleitern versetzt werden müssen.",-1),e("div",{"data-hint-kind":"caution",class:"danger custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"caution","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"m10.3 4-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.7-3l-8-14a2 2 0 0 0-3.4 0Z"}),e("path",{d:"M12 9v4m0 4v.1"})]),n("Achtung")]),e("p",null,"Grundschulen können fast immer den hier unten dargestellten Weg wählen. Veraltete Anleitungen aus SchILD2, die die Versetzung über Gruppenprozesse erklären, sollen nicht mehr verwendet werden!")],-1),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),n("Tipp")]),e("p",null,[n('Wie ein Abschnitt heißt, also "Halbjahr", "Abschnitt* oder "Semester", kann über '),e("em",null,"Verwaltung ➜ Schule ➜ Allgemeine Angaben ➜ Angaben zu Abschnitten"),n(" ➜ "),e("strong",null,"Allgemeine Bezeichnung für"),n(" eingestellt werden werden.*")])],-1),s('<h2 id="_1-abschnittswechsel-ohne-versetzung-–-halbjahreswechsel" tabindex="-1">1. Abschnittswechsel ohne Versetzung – Halbjahreswechsel <a class="header-anchor" href="#_1-abschnittswechsel-ohne-versetzung-–-halbjahreswechsel" aria-label="Permalink to &quot;1. Abschnittswechsel ohne Versetzung – Halbjahreswechsel&quot;">​</a></h2><p>Findet ein Abschnittswechsel vom 1. ins 2. Halbjahr statt, wird keine Versetzung durchgeführt.</p><p>Bei diesem Abschnittswechseln geht es lediglich darum, die Schule in den neuen Abschnitt zu übertragen, neue Lernabschnitte anzulegen und Fächer und Kurse nach Bedarf mitnehmen bzw. im neuen Lernabschnitt passend neu anzulegen.</p><p>Arbeiten Sie sich zum Ende des Halbjahres durch eventuell für den Zeugnisdruck erhobene Leistungsdaten. Relevant sind diese auch für eventuell anliegende Abschlussprognosen, z.B. im Jahrgang 9.</p><p>Sofern in der entsprechenden APO für einen Jahrgang vorgesehen ist, dass zum Schuljahreswechsel eine Versetzung vorgesehen ist, sollte hier auf das beabsichtigte Setzen von Mahnungen geachtet werden.</p><p><a href="/bilder/grundlagen/schueler-versetzung-1.png"><img src="'+a+'" alt="Abschnittwechsel werden über Verwaltung vorgenommen." loading="lazy"></a></p><p><em>Abschnittwechsel werden über Verwaltung vorgenommen.</em></p><p>Gehen Sie einfach auf <strong>Verwaltung</strong> und wählen Sie dann ihren Wechsel. Da die verwendete Beispielschule Halbjahre verwendet und sich im 1. Halbjahr befindet, wird hier passend die Schaltfläche <strong>Halbjahreswechsel durchführen</strong> eingeblendet.</p><p>Klicken Sie den Button <strong>Halbjahreswechsel durchführen</strong>.</p><p><a href="/bilder/grundlagen/schueler-versetzung-2.png"><img src="'+h+'" alt="Auswahlmöglichkeiten bei Abschnittswechseln." loading="lazy"></a></p><p><em>Auswahlmöglichkeiten bei Abschnittswechseln.</em></p><p>Sie werden dann automatisch durch den Wechsel geleitet und die Haken sind in der Regel so wie eingestellt zu belassen.</p><p>Die Einstellungen bei Abschnittswechseln sind hierarchisch in sinnvoller Reihenfolge aufgebaut. Damit etwa bei <em>4.</em> Schüler in einen Abschnitt eingetragen werden können, muss dieser natürlich zuvor, bei <em>3.</em> angelegt worden sein. Und damit dieses geschehen kann, muss zuvor bei <em>2.</em> der entsprechende Abschnitt für die Schule erzeugt worden sein. Wählen Sie einen Haken ab, werden daher alle folgenden Haken ebenfalls abgewählt.</p><p>Bitte kontrollieren Sie, ob der Haken zur Mitnahme der Fächer wie gewünscht gesetzt ist.</p>',14),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,[e("strong",null,"Hinweise zum Schuljahreswechsel:")]),e("ol",null,[e("li",null,"In der Regel ist die Mitnahme der Fächer gewünscht."),e("li",null,"Die Angaben zu Beginn und Ende sind optional."),e("li",null,"Sind Schritte in der Übersicht ausgegraut, wurde der entsprechende Schritt schon ausgeführt.")])],-1),e("p",null,[e("a",{href:"/bilder/grundlagen/schueler-versetzung-3.png"},[e("img",{src:u,alt:"Neustart erforderlich.",loading:"lazy"})])],-1),e("p",null,[e("em",null,"Neustart erforderlich.")],-1),e("div",{"data-hint-kind":"right",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"right","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"m8 12 3 3 5-6"})]),n("Richtig – Fertig")]),e("p",null,"Nach Abschluss des Wechsels beendet sich SchILD 3 und muss manuell neu gestartet werden. Hierbei werden alle veränderten Kataloge, zum Beispiel die Kurse, neu und vollständig geladen.")],-1),e("hr",null,null,-1),e("h2",{id:"_2-abschnittswechsel-mit-versetzung-abschlussen-ausschulungen-–-schuljahreswechsel",tabindex:"-1"},[n("2. Abschnittswechsel mit Versetzung, Abschlüssen, Ausschulungen – Schuljahreswechsel "),e("a",{class:"header-anchor",href:"#_2-abschnittswechsel-mit-versetzung-abschlussen-ausschulungen-–-schuljahreswechsel","aria-label":'Permalink to "2. Abschnittswechsel mit Versetzung, Abschlüssen, Ausschulungen – Schuljahreswechsel"'},"​")],-1),e("p",null,"Am Ende des Schuljahres muss der Abschnittswechsel mit eventueller Versetzung bzw. Ausschulung - mit Abschluss oder als Abgänger, wenn die Schule verlassen wird - durchgeführt werden.",-1),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis – Grundschule: Jahrgang 04")]),e("p",null,[n("In SchILD-NRW 3.6.0 ist beim Schuljahreswechsel für den "),e("strong",null,"Grundschuljahrgang 04"),n(" die Versetzungsart "),e("strong",null,"„Versetzt“"),n(" zu verwenden, statt „Abschluss“.")])],-1),s('<p><a href="/bilder/grundlagen/schueler-versetzung-7-versetzungstabelle.png"><img src="'+d+'" alt="In der Versetzungstabelle, erreichbar über Kataloge ➜ Schulinterne Kataloge ➜ Klassen-/Versetzungstabelle ist hinterlegt, auf welche Klasse welche andere folgt und wer in der Klasse Klassenleitungsteam ist." loading="lazy"></a></p><p><em>In der Versetzungstabelle, erreichbar über Kataloge ➜ Schulinterne Kataloge ➜ Klassen-/Versetzungstabelle ist hinterlegt, auf welche Klasse welche andere folgt und wer in der Klasse Klassenleitungsteam ist.</em></p><p>Grundsätzlich legt die <em>Versetzungstabelle</em> den Standard fest, wie mit Personen einer Klasse bei der Versetzung zu verfahren ist.</p><p>Bei der Versetzung kann es zu zwei Varianten kommen:</p><ul><li>Es wurden die Versetzungsvermerke automatisch und mit nach manueller Prüfung. Gleiches gilt für eventuelle Abschlüsse oder Abschlussprognosen. Dies wird in Jahrgängen durchgeführt, in denen Versetzungen und Abschlüsse anliegen.</li><li>Es wurden eventuell keine Versetzungsberechnungen durchgeführt, z.B. weil keine Zeugnisse mit ScHILD gedruckt wurden oder weil es in den entsprechenden Jahrgängen keine Versetzungen oder Abschlüsse gibt.</li></ul><p>Beide Varianten können an derselben Schule vorkommen. An einer Gesamtschule gibt es in den unteren Jahrgängen in der Regel keine Nichtversetzung. Im Abschlussjahrgang müssen die Abschlüsse dagegen individuell festgelegt werden. Für den Wechsel aus Jahrgang 10 in die EF sind die passende Qualifikation und die Anmeldung zur gymnasialen Oberstufe zu berücksichtigen.</p><p>In beiden Fällen wird der Abschnittswechsel über <em>Verwaltung ➜ Schule bearbeiten</em> durchgeführt.</p>',7),e("div",{"data-hint-kind":"caution",class:"danger custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"caution","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"m10.3 4-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.7-3l-8-14a2 2 0 0 0-3.4 0Z"}),e("path",{d:"M12 9v4m0 4v.1"})]),n("Achtung")]),e("p",null,"Im Fall von leeren Versetzungsvermerken muss beachtet werden, das SchILD-NRW bei diesen davon ausgeht, dass der Schülerdatensatz versetzt werden soll.")],-1),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),n("Tipp")]),e("p",null,[n("Es empfiehlt sich, bei Ausnahmen, also Wiederholer oder Vorversetzte, die entsprechenden Einstellungen im "),e("em",null,"aktuellen Lernabschnitt"),n(" von Hand einzutragen, auch wenn der Rest des Jahrgangs unbearbeitet bleibt.")]),e("p",null,[n("Bei kleineren Systemen kann es sinnvoll sein, die wenigen Sonderfälle direkt bei der Versetzung mit im Fenster"),e("em",null,"Daten prüfen"),n(" einzustellen. In größeren Schulen mit Abteilungen für die Jahrgänge, sollten diese Vorgaben im Vorfeld durch die Abteilungen eingestellt worden sein.")])],-1),e("p",null,[e("a",{href:"/bilder/grundlagen/schueler-versetzung-4.png"},[e("img",{src:c,alt:"Den Schuljahreswechsel anstoßen. Wählen Sie das Verhalten mit Kursen, wie es zu Ihrem System passt.",loading:"lazy"})])],-1),e("p",null,[e("em",null,"Den Schuljahreswechsel anstoßen. Wählen Sie das Verhalten mit Kursen, wie es zu Ihrem System passt.")],-1),e("p",null,[n("Sind Sie bereit, den Schuljahreswechsel durchzuführen - das heißt, die Verarbeitung des alten Schuljahres und alle Vorbereitungen sind abgeschlossen - drücken Sie den Button "),e("strong",null,"Schuljahreswechsel durchführen"),n(".")],-1),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,"Achten Sie im folgenden Menü darauf, dass der Haken zu den Fächern wie gewünscht gesetzt ist.")],-1),s('<p><a href="/bilder/grundlagen/schueler-versetzung-5-datenpruefen.png"><img src="'+o+'" alt="Übersicht aller Aktiven mit den zuvor eingestellten Versetzungsbedingungen. Diese können hier noch verändert werden." loading="lazy"></a></p><p><em>Übersicht aller Aktiven mit den zuvor eingestellten Versetzungsbedingungen. Diese können hier noch verändert werden.</em></p><p>Es öffnet sich das Fenster <strong>Daten prüfen</strong>, in dem die zuvor für den Lernabschnitt automatisch oder manuell eingestellten Versetzungsergebnisse zu finden sind.</p><p>Diese können hier noch individuell angepasst werden. Hier im Beispiel wurde für einige aus unterschiedlichen Gründen Nicht-Versetzte der neue Jahrgang mit dann neuer Nachfolgeklasse gewählt.</p><p>Klicken Sie auf <strong>Fertigstellen</strong>, wenn Versetzung und Schuljahreswechsel so in Ordnung erscheinen oder beenden Sie den Prozess ohne dass bislang Änderungen an der Datenbank vorgenommen wurden über <strong>Abbrechen</strong>.</p><p>Es öffnet sich ein Fenster, das mit <strong>Ok</strong> bestätigt wird.</p><p>SchILD meldet nach Abschluss des Schuljahreswechsels eben dieses mit einem Fenster, nach der Bestätigung schließt sich das Programm.</p>',7),e("div",{"data-hint-kind":"right",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"right","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"m8 12 3 3 5-6"})]),n("Richtig – Fertig")]),e("p",null,"Nach Abschluss des Wechsels beendet sich SchILD 3 und muss manuell neu gestartet werden. Hierbei werden alle veränderten Kataloge, zum Beispiel die Kurse, neu und vollständig geladen.")],-1),s('<h3 id="sich-anschließende-arbeiten" tabindex="-1">Sich anschließende Arbeiten <a class="header-anchor" href="#sich-anschließende-arbeiten" aria-label="Permalink to &quot;Sich anschließende Arbeiten&quot;">​</a></h3><p>Sofern vor der Versetzung die <em>Versetzungstabelle</em> nicht schon vor dem Versetzungsprozess angepasst wurde, wären nun noch die neuen Klassenleitungsteams einzustellen.</p><p>Passen Sie den Katalog <strong>Klassen- und Versetzungstabelle</strong> an und übernehmen Sie die neuen Klassenlehrkräfte, indem Sie auf <code>Aktuelle Angaben in Schülerdaten übernehmen</code> anklicken. Bestätigen Sie das folgende Fenster, auch wenn Sie keinen Eintrag für &quot;Klassenleitung&quot; anhaken können.</p><p>Die eventuell vorher noch vorhandenen Schüler in Abschlussklassen haben nun nicht mehr den Status <em>Aktiv</em>, sondern sind <em>Abgänger</em> oder haben einen <em>Abschluss</em>. In größeren Systemen mit unterschiedlichen Abschlüssen sollten diese Klassen vor der Versetzung zusammen mit dem Zeugnisdruck schon passend ausgeschult werden.</p><p>Die Eingangsjahrgänge der Schule sind nun leer, so dass die Schüler aus der <em>Neuaufnahme</em> über Gruppenprozesse <em>Aktiv</em> geschaltet werden und auf ihre vorgesehenen Klassen verteilt werden können.</p><p>Über die entsprechenden Werkzeuge sind ebenfalls passende Fächer, Kurse und Lehrkräfte einzutragen.</p><p><a href="/schild3/">index.php?title=Kategorie:SchILD-NRW</a> <a href="/zeugnisse/">index.php?title=Kategorie:Versetzung</a> <a href="/zeugnisse/">index.php?title=Kategorie:Zeugnisse</a></p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Versetzung_ins_neue_Schuljahr_und_Abschnittswechsel_durchf%C3%BChren_(Einf%C3%BChrung_in_SchILD-NRW)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 7170.</p>',9)])])}const S=t(g,[["render",b]]);export{z as __pageData,S as default};
